k = input(7, "K Neighbors", 1, 20, 1)
featLen = input(20, "Feature Lookback", 5, 40, 1)
histSearch = input(200, "History Search", 30, 500, 5)
mThr = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
gThr = input(0.35, "Disagreement Threshold", 0.05, 1.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

varip fHist = array(0)
varip cHist = array(0)

nHist = array.size(cHist)
prevC = close
if nHist > 0 { prevC := cHist[nHist - 1] }

fCur = 0.0
if prevC != 0 { fCur := (close - prevC) / prevC }

array.push(fHist, fCur)
array.push(cHist, close)

nBars = array.size(cHist)
curIdx = nBars - 1

upCount = 0
downCount = 0
M = 0.0
G = 1.0

ready = nBars >= featLen + 2 and bar_index >= featLen + 5
if ready {
    bestDist = array()
    bestLab = array()
    ii = 0
    while ii < k {
        array.push(bestDist, 999999999.0)
        array.push(bestLab, 0)
        ii := ii + 1
    }
    searchBack = histSearch
    if nBars - 2 < searchBack { searchBack := nBars - 2 }
    jStart = curIdx - searchBack
    minJ = featLen - 1
    if jStart < minJ { jStart := minJ }
    jEnd = curIdx - 1
    jj = jStart
    while jj <= jEnd {
        dsum = 0.0
        nn = 0
        while nn < featLen {
            a = fHist[curIdx - featLen + 1 + nn]
            b = fHist[jj - featLen + 1 + nn]
            diff = a - b
            dsum := dsum + diff * diff
            nn := nn + 1
        }
        dist = sqrt(dsum)
        insIdx = -1
        mm = 0
        while mm < k {
            if dist < bestDist[mm] {
                insIdx := mm
                mm := k
            }
            mm := mm + 1
        }
        if insIdx >= 0 {
            mm = k - 1
            while mm > insIdx {
                array.set(bestDist, mm, bestDist[mm - 1])
                array.set(bestLab, mm, bestLab[mm - 1])
                mm := mm - 1
            }
            lab = -1
            if cHist[jj + 1] > cHist[jj] { lab := 1 }
            array.set(bestDist, insIdx, dist)
            array.set(bestLab, insIdx, lab)
        }
        jj := jj + 1
    }
    vv = 0
    tu = 0
    td = 0
    while vv < k {
        if bestDist[vv] < 999999999.0 {
            if bestLab[vv] == 1 { tu := tu + 1 }
            else { td := td + 1 }
        }
        vv := vv + 1
    }
    upCount := tu
    downCount := td
    tot = tu + td
    if tot > 0 {
        M := (tu - td) / tot
        G := 1.0 - abs(M)
    }
}

bullCond = M > mThr and G < gThr and ready
bearCond = M < 0 - mThr and G < gThr and ready
buySig = bullCond and not bullCond[1]
sellSig = bearCond and not bearCond[1]

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 0, "separate")
}

mCol = "#22cc88"
if M < 0 { mCol := "#ff4477" }

plot(M, "Vote Margin", "#22cc88", 2, "separate")
plot(G, "Disagreement", "#ffd43b", 2, "separate")
hline(mThr, "#22cc88", "separate")
hline(0 - mThr, "#ff4477", "separate")
plot3d(M, "Margin Towers", "bars3d", mCol, "separate", 0)
plot3d(G, "Disagreement Cloud", "scatter", "#ffd43b", "separate", 1)

// Visible Session Volume Value Model
// Volume-profile-on-chart: POC + value area from visible session, leaving-value signals.

profRows = input(24, "ProfileRows", 10, 48, 1)
vaPct = input(70, "ValueAreaPercent", 50, 90, 5)
useVis = input(true, "UseVisibleSession")
showHist = input(true, "ShowValueHistogram")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range (expanding session when enabled) ───
sessLen = bar_index + 1
lookN = sessLen
if useVis == false {
    lookN := 100
}
if lookN > sessLen {
    lookN := sessLen
}
if lookN < profRows {
    lookN := profRows
}
if lookN < 24 {
    lookN := 24
}

hh = highest(high, lookN)
ll = lowest(low, lookN)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
if rng < 0.000001 {
    rng := close * 0.01
}

// ─── Build bin volumes from visible session bars ───
binVol = array()
b = 0
while b < profRows {
    array.push(binVol, 0.0)
    b := b + 1
}

j = 0
while j < lookN {
    tp = (high[j] + low[j] + close[j]) / 3
    vv = volume[j]
    idx = floor((tp - ll) / rng * profRows)
    if idx < 0 {
        idx := 0
    }
    if idx > profRows - 1 {
        idx := profRows - 1
    }
    cur = array.get(binVol, idx)
    array.set(binVol, idx, cur + vv)
    j := j + 1
}

totalVol = array.sum(binVol)

// ─── Point of control: bin with highest volume ───
pocBin = 0
pocVal = array.get(binVol, 0)
k = 1
while k < profRows {
    v = array.get(binVol, k)
    if v > pocVal {
        pocVal := v
        pocBin := k
    }
    k := k + 1
}
pocPrice = ll + (pocBin + 0.5) / profRows * rng

// ─── Value area: expand from POC until >= ValueAreaPercent ───
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profRows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < profRows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < profRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        } else {
            if vaHigh < profRows - 1 {
                vaHigh := vaHigh + 1
                accum := accum + rightVal
            }
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) / profRows * rng
valPrice = ll + vaLow / profRows * rng

insideVA = close >= valPrice and close <= vahPrice
inside1 = insideVA[1]
inside2 = insideVA[2]
leavingValue = not insideVA and inside1 and inside2

buySig = leavingValue and close > vahPrice
sellSig = leavingValue and close < valPrice

// ─── Volume concentration for terrain height (price-denominated) ───
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVal / totalVol * 100
}
vaWidth = vahPrice - valPrice
terrainSurf = pocPrice + pocShare / 100 * rng * 0.5 + (close - pocPrice) * 0.1
histProxy = pocShare
if showHist == false {
    histProxy := 0.0
}

// ─── Signals: price leaving value (2D markers) ───
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// ─── 3D signal cones in the same pane ───
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 2, "3d")
}
if leavingValue {
    label3d(bar_index, close, "Leaving Value", "#ffd43b", 1.0, 1, "3d")
}

// ─── 2D: same POC / VAH / VAL information when 3D is off ───
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(close, "Price", "#ffffff", 1)
plot(histProxy, "POC Share", "#b48cff", 1, "separate")
fill(vahPrice, valPrice, "rgba(68,136,255,0.12)")

// ─── 3D: value terrain + POC labelled rail + value-area edge rails ───
plot3d(terrainSurf, "Value Terrain", "surface", "#4488ff", "3d", 3)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 0)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 1)
label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 0, "3d")

